"""Pravix Flow — the n389 build's own checks (Nov 15 2026): Flow's code is pieces by feature, and its three script files
are built from them (reorganisation, stage 3b). The code is in _source/flow/, one small file per piece, named
feature.piece.js; order.json lists the pieces in the order they run; _ci/build_flow.py joins them into assets/flow/app.js,
layers.js and layers2.js, which the page loads as before. The seal runs the build first. A built file is never edited:
it carries the SHA-256 of its body, and a built file changed by hand is refused."""
import os, re, json, shutil, tempfile, hashlib
from core import ok, section, PORT, INIT, FAKE, WRAP, SEED, BUILD
import build_flow

FU = '{"uid":"u1","email":"daniel.giordano@pravix.app","displayName":"Daniel Giordano"}'
newerr = lambda e: [x for x in e if 'cb is not a function' not in x and 'collectionGroup' not in x]
rd = lambda *p: open(os.path.join(BUILD, *p), encoding='utf-8', newline='').read()
HEAD = re.compile(r'\n/\* ━━━━━ (\d+) of (\d+) · (.*?) ━━━━━ \*/\n')


def copy_of_flow():
    """a throwaway copy of what the build reads and writes"""
    t = tempfile.mkdtemp(prefix='t389-'); os.makedirs(os.path.join(t, 'assets')); shutil.copytree(os.path.join(BUILD, 'assets', 'flow'), os.path.join(t, 'assets', 'flow')); shutil.copytree(os.path.join(BUILD, '_source'), os.path.join(t, '_source'))
    shutil.copy(os.path.join(BUILD, 'index.html'), os.path.join(t, 'index.html')); return t


@section(id='t389', title='n389 · Flow’s code is pieces by feature in _source/flow/, and app.js, layers.js and layers2.js are built from them in a stated order; a built file is never edited',
         apps=['flow'], topics=['performance', 'security'], engines=('chromium', 'webkit'))
async def s_t389(br):
    S = os.path.join(BUILD, '_source', 'flow'); o = json.loads(rd('_source', 'flow', 'order.json'))
    listed = list(o['app.js']) + [p['file'] for p in o['layers.js']] + [p['file'] for p in o['layers2.js']]; have = sorted(f for f in os.listdir(S) if f.endswith('.js'))
    ok('The pieces · every piece in _source/flow/ is listed in order.json exactly once, and every listed piece is there (a piece nobody lists would never run)',
       sorted(listed) == have and len(listed) == len(set(listed)) and len(o['app.js']) >= 74 and len(o['layers.js']) >= 63 and len(o['layers2.js']) >= 41, [len(have), len(listed)])
    feats = sorted(set(f.split('.')[0] for f in listed))
    ok('…each is named feature.piece.js, and the features are the app’s own parts (the drawer, the board, add patient, the care team, disposition, search …)',
       all(re.fullmatch(r'[a-z0-9-]+\.[a-z0-9-]+\.js', f) for f in listed) and {'drawer', 'board', 'add-patient', 'care-team', 'disposition', 'search', 'core', 'backend', 'hig'} <= set(feats), feats)
    ok('…the first three pieces of the main script are the shared parts: the helpers, pvxWatch and the layers', o['app.js'][:3] == ['core.helpers.js', 'core.watch.js', 'core.steps.js'] and 'function pvxEsc(' in rd('_source', 'flow', 'core.helpers.js') and 'var pvxWatch=' in rd('_source', 'flow', 'core.watch.js') and 'function pvxRun(' in rd('_source', 'flow', 'core.steps.js'), o['app.js'][:3])
    want = build_flow.built(BUILD); disk = {b: rd('assets', 'flow', b) for b in build_flow.BUILT}
    ok('The built files · app.js, layers.js and layers2.js are exactly what the pieces give, joined in the order of order.json (python3 _ci/seal_csp.py . builds them)', all(want[b] == disk[b] for b in build_flow.BUILT), [b for b in build_flow.BUILT if want[b] != disk[b]])
    heads = {b: build_flow.HASH.search(disk[b][:2000]) for b in build_flow.BUILT}
    ok('…each says at its top that it is built and must not be edited, and carries the SHA-256 of its body', all(heads[b] and 'BUILT by _ci/build_flow.py' in disk[b][:300] and 'Do not edit this file' in disk[b][:400] and hashlib.sha256(disk[b][heads[b].end():].encode()).hexdigest()[:16] == heads[b].group(1) for b in build_flow.BUILT))
    H = HEAD.findall(disk['layers.js']) + HEAD.findall(disk['layers2.js']); total = len(o['layers.js']) + len(o['layers2.js'])
    ok('…the blocks are numbered in the order they run, 1 to N across the two files, each under the title order.json gives it', [int(k) for k, n, t in H] == list(range(1, total + 1)) and all(int(n) == total for k, n, t in H) and [t for k, n, t in H] == [p['title'] for p in o['layers.js'] + o['layers2.js']], len(H))
    raw = [p['file'] for p in o['layers.js'] + o['layers2.js'] if p.get('wrap', True) is False]
    ok('…every block still runs inside its own try/catch, added by the build; three are kept as written because what they declare for the whole page sits outside it', len(raw) == 3 and (disk['layers.js'] + disk['layers2.js']).count(build_flow.CATCH) >= total - len(raw) and all(('try{\n' + rd('_source', 'flow', p['file']) + '\n' + build_flow.CATCH + '\n') in disk[b] for b in ('layers.js', 'layers2.js') for p in o[b] if p.get('wrap', True)), raw)
    idx = rd('_source', 'flow', 'INDEX.md')
    ok('INDEX.md · the map of the code is current: every piece by feature, and each function that has layers with the pieces that add them (fillDrawer: its own code in drawer.fill-drawer.js, 8 layers)',
       idx == build_flow.index(BUILD) and all('`%s`' % f in idx for f in listed) and bool(re.search(r'\| `fillDrawer` \| `drawer\.fill-drawer\.js` \| (?:`[\w.-]+` (?:wrap|after|before)(?: · )?){8} \|', idx)), [l for l in idx.split('\n') if l.startswith('| `fillDrawer`')])
    ok('…and nothing needs building: python3 _ci/build_flow.py . --check', build_flow.build(BUILD, write=False) == [] and build_flow.edited_by_hand(BUILD) == [])

    t = copy_of_flow()
    try:
        with open(os.path.join(t, 'assets', 'flow', 'layers2.js'), 'a', encoding='utf-8') as f: f.write('\n// a change made in the built file\n')
        refused = ''
        try: build_flow.build(t)
        except SystemExit as x: refused = str(x)
        ok('A built file changed by hand is refused, not overwritten: the build says which file and where the code is', build_flow.edited_by_hand(t) == ['layers2.js'] and 'EDITED BY HAND' in refused and '_source/flow' in refused and 'a change made in the built file' in open(os.path.join(t, 'assets', 'flow', 'layers2.js'), encoding='utf-8').read(), refused[:120])
    finally: shutil.rmtree(t, ignore_errors=True)
    t = copy_of_flow()
    try:
        piece = o['layers2.js'][-1]['file']
        with open(os.path.join(t, '_source', 'flow', piece), 'a', encoding='utf-8') as f: f.write('\n/* t389: a change made in the piece */')
        ch = build_flow.build(t); new = open(os.path.join(t, 'assets', 'flow', 'layers2.js'), encoding='utf-8', newline='').read()
        ok('A change made in a piece reaches the built file on the next build, and only the file that piece belongs to changes', ch == ['assets/flow/layers2.js'] and 't389: a change made in the piece' in new and new != disk['layers2.js'] and build_flow.build(t, write=False) == [], ch)
        open(os.path.join(t, '_source', 'flow', 'drawer.stray.js'), 'w').write('/* never listed */'); stray = ''
        try: build_flow.build(t)
        except SystemExit as x: stray = str(x)
        ok('…and a piece that order.json does not list stops the build (it would never run)', 'drawer.stray.js' in stray and 'does not list' in stray, stray[:120])
    finally: shutil.rmtree(t, ignore_errors=True)

    html = rd('index.html'); sw = rd('sw.js')
    ok('The page · loads the same three script files from assets/flow/ as before; nothing on the page or in the service worker asks for _source/', '_source' not in html and '_source' not in sw and re.findall(r'src="/assets/flow/([a-z0-9]+\.js)\?v=', html) == ['app.js', 'layers.js', 'layers2.js'])
    c = await br.new_context(viewport={'width': 1440, 'height': 900}, timezone_id='America/Los_Angeles', locale='en-US', color_scheme='dark', service_workers='block')
    await c.add_init_script(INIT.replace('@@USER@@', FU).replace('@@SEED@@', SEED)); await c.add_init_script(FAKE); await c.add_init_script(WRAP); seen = []
    async def route(r):
        u = r.request.url
        if u.startswith(f'http://127.0.0.1:{PORT}/'): seen.append(u[len(f'http://127.0.0.1:{PORT}'):]); await r.continue_()
        elif u.startswith('https://www.gstatic.com/'): await r.fulfill(status=200, content_type='application/javascript', body='')
        else: await r.fulfill(status=204, body='')
    await c.route('**/*', route); p = await c.new_page(); e = []; p.on('pageerror', lambda x: e.append(str(x)))
    await p.goto(f'http://127.0.0.1:{PORT}/'); await p.wait_for_selector('#subnavFlow .switcher.pvx-sw', state='attached'); await p.wait_for_timeout(2400)
    r = await p.evaluate("({fns:[typeof renderAll, typeof openDrawer, typeof pvxEsc, typeof pvxWatch, typeof pvxSteps, typeof window.pvxSeg, typeof window.pvxOverlay], layers:pvxSteps.names().length, watchers:pvxWatch.count()})")
    ok('…and Flow runs from the built files: the main script, the shared parts and the blocks are all there, and the browser never asks for a piece', r['fns'][:5] == ['function', 'function', 'function', 'function', 'object'] and r['fns'][5] == 'function' and r['layers'] == 55 and r['watchers'] == 23 and not any('_source' in u for u in seen), [r, [u for u in seen if '_source' in u][:3]])
    ok('No page errors', not newerr(e), newerr(e)[:3]); await c.close()
